'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import IdleScreen from '@/components/IdleScreen'
import CountdownScreen from '@/components/CountdownScreen'
import ResultScreen from '@/components/ResultScreen'
import { useCameraCapture } from '@/lib/camera'

type ScreenState = 'IDLE' | 'COUNTDOWN' | 'RESULT'

interface Photo {
  id: number
  url: string
  color: string
  label: string
}

export default function Home() {
  const [currentScreen, setCurrentScreen] = useState<ScreenState>('IDLE')
  const [photos, setPhotos] = useState<Photo[]>([])
  const [flashActive, setFlashActive] = useState(false)
  const captureIntervalRef = useRef<number | null>(null)
  const flashTimeoutRef = useRef<number | null>(null)

  const { videoRef, capture, isCameraReady } = useCameraCapture()

  const clearCaptureLoop = useCallback(() => {
    if (captureIntervalRef.current) {
      window.clearInterval(captureIntervalRef.current)
      captureIntervalRef.current = null
    }

    if (flashTimeoutRef.current) {
      window.clearTimeout(flashTimeoutRef.current)
      flashTimeoutRef.current = null
    }
  }, [])

  const transitionToScreen = useCallback((screen: ScreenState) => {
    setCurrentScreen(screen)
    if (screen !== 'RESULT') {
      setPhotos([])
    }
    if (screen !== 'COUNTDOWN') {
      setFlashActive(false)
      clearCaptureLoop()
    }
  }, [clearCaptureLoop])

  const capturePhotos = useCallback(() => {
    clearCaptureLoop()

    let step = 0
    const totalSteps = 9

    const interval = window.setInterval(() => {
      step += 1
      const cycle = Math.floor((step - 1) / 3)
      const position = (step - 1) % 3

      if (position === 0 && step > 1) {
        setFlashActive(true)
        flashTimeoutRef.current = window.setTimeout(() => setFlashActive(false), 500)
      }

      if (position === 0 && isCameraReady) {
        const photo = capture()
        if (photo) {
          setPhotos((prev) => {
            const next = [...prev]
            next[cycle] = photo
            return next
          })
        }
      }

      if (step === totalSteps) {
        window.clearInterval(interval)
        captureIntervalRef.current = null
        window.setTimeout(() => {
          transitionToScreen('RESULT')
        }, 500)
      }
    }, 1200)

    captureIntervalRef.current = interval
  }, [capture, clearCaptureLoop, isCameraReady, transitionToScreen])

  const handleStart = useCallback(() => {
    setPhotos([])
    setFlashActive(false)
    transitionToScreen('COUNTDOWN')
    capturePhotos()
  }, [capturePhotos, transitionToScreen])

  useEffect(() => {
    if (currentScreen === 'RESULT') {
      const timer = window.setTimeout(() => {
        transitionToScreen('IDLE')
      }, 30000)
      return () => window.clearTimeout(timer)
    }
  }, [currentScreen, transitionToScreen])

  useEffect(() => {
    if (currentScreen !== 'COUNTDOWN') {
      clearCaptureLoop()
    }
  }, [clearCaptureLoop, currentScreen])

  return (
    <div className="kiosk-lock flex items-center justify-center bg-[#0a0a0f]">
      {currentScreen === 'IDLE' && <IdleScreen onStart={handleStart} />}

      {currentScreen === 'COUNTDOWN' && (
        <CountdownScreen
          onComplete={() => transitionToScreen('RESULT')}
          videoRef={videoRef}
        />
      )}

      {currentScreen === 'RESULT' && (
        <ResultScreen
          photos={photos}
          onFinish={() => transitionToScreen('IDLE')}
        />
      )}

      {flashActive && (
        <div className="flash-overlay fixed inset-0 z-[200] bg-white" />
      )}
    </div>
  )
}
